-- reviewed by hand. The waveform_peaks_valid function below is hand-written: drizzle-kit does
-- not manage functions, and the work_logs check constraint depends on it, so it is created first.
CREATE SCHEMA "toph";
--> statement-breakpoint
-- Validates stored waveform peaks: a JSON array of at most 2,048 numbers, each between 0 and 1.
-- JSON numbers are always finite, so NaN/Infinity cannot be stored here.
CREATE FUNCTION "toph"."waveform_peaks_valid"(peaks jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT jsonb_typeof(peaks) = 'array'
     AND jsonb_array_length(peaks) <= 2048
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(peaks) AS element
       WHERE jsonb_typeof(element) <> 'number'
          OR (element::text)::numeric < 0
          OR (element::text)::numeric > 1
     );
$$;
