CREATE TABLE "toph"."dashboard_metric_snapshots" (
	"id" uuid PRIMARY KEY NOT NULL,
	"farm_id" uuid NOT NULL,
	"as_of_date" date NOT NULL,
	"recordings_today" integer NOT NULL,
	"new_recordings" integer NOT NULL,
	"active_workers" integer NOT NULL,
	"response_accuracy" numeric(5, 2),
	"source" text NOT NULL,
	"source_notes" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "dashboard_metric_snapshots_farm_id_as_of_date_unique" UNIQUE("farm_id","as_of_date"),
	CONSTRAINT "snapshots_counts_nonnegative" CHECK (recordings_today >= 0 AND new_recordings >= 0 AND active_workers >= 0),
	CONSTRAINT "snapshots_new_lte_recordings" CHECK (new_recordings <= recordings_today),
	CONSTRAINT "snapshots_accuracy_range" CHECK (response_accuracy IS NULL OR (response_accuracy >= 0 AND response_accuracy <= 100)),
	CONSTRAINT "snapshots_source_nonempty" CHECK (length(btrim(source)) > 0)
);
