CREATE TABLE "toph"."work_logs" (
	"id" uuid PRIMARY KEY NOT NULL,
	"farm_id" uuid NOT NULL,
	"employee_id" uuid NOT NULL,
	"field_id" uuid NOT NULL,
	"activity" text NOT NULL,
	"work_date" date NOT NULL,
	"start_at" timestamp with time zone NOT NULL,
	"end_at" timestamp with time zone NOT NULL,
	"summary" text NOT NULL,
	"transcript" text,
	"is_new" boolean DEFAULT false NOT NULL,
	"recording_path" text,
	"recording_duration_seconds" double precision,
	"recording_is_demo" boolean DEFAULT false NOT NULL,
	"waveform_asset_path" text,
	"waveform_peaks" jsonb,
	"waveform_source" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "work_logs_farm_id_id_unique" UNIQUE("farm_id","id"),
	CONSTRAINT "work_logs_activity_nonempty" CHECK (length(btrim(activity)) > 0),
	CONSTRAINT "work_logs_end_after_start" CHECK (end_at > start_at),
	CONSTRAINT "work_logs_recording_duration_valid" CHECK (recording_duration_seconds IS NULL OR (recording_path IS NOT NULL AND recording_duration_seconds > 0 AND recording_duration_seconds < 'Infinity'::double precision)),
	CONSTRAINT "work_logs_waveform_source_valid" CHECK (waveform_source IS NULL OR waveform_source IN ('design_reference', 'audio')),
	CONSTRAINT "work_logs_waveform_peaks_valid" CHECK (waveform_peaks IS NULL OR toph.waveform_peaks_valid(waveform_peaks))
);
